/**
 * Refuses the call when `actor` no longer holds a live membership. A session
 * minted before the removal is not enough: every action re-reads the row.
 */
export async function assertCurrentActor(actor: Actor): Promise<void> {
  if (actor.isPlatformStaff === true) return;
  const member = await memberRepo.findMember(actor.orgId, actor.userId);
  if (!member || !isCurrentMember(member)) {
    throw new Error("You are not a member of that organization");
  }
}

/**
 * Work can be given only to someone who is a current member of this
 * workspace. `null` means "nobody" and is always allowed. Anyone else — a
 * former member, a member of another workspace, a user who never joined —
 * refuses the whole change.
 */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || !isCurrentMember(member)) {
    throw new Error(
      `User ${userId} is not a current member of this workspace`,
    );
  }
}

