input.new_string:
  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // Accepting consumes the invitation whoever the acceptor is. A person who
  // is already a current member keeps their role and their seat.
  if (existing && isCurrentMember(existing)) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  // A former member comes back as the same row: history stays attached, and
  // the invitation supplies the role, the inviter and the new join date.
  const member =
    existing === null
      ? await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
        )
      : await memberRepo.reinstateMember(invitation.orgId, existing.id, {
          role: invitation.role,
          invitedBy: invitation.invitedBy,
          joinedAt: acceptedAt,
        });

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

